import{_ as l,o as e,c as i,O as t}from"./chunks/framework.ac0f74f3.js";const r="/assets/cc-kclb.97035d26.png",o="/assets/cc-kclb2.ca14a927.png",h="/assets/cc-kclb6.128439bc.png",s="/assets/cc-kclb5.da64e354.png",m=JSON.parse('{"title":"库存列表","description":"","frontmatter":{},"headers":[],"relativePath":"仓储管理/库存列表.md","filePath":"仓储管理/库存列表.md"}'),n={name:"仓储管理/库存列表.md"};function c(u,a,d,p,_,b){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="库存列表" tabindex="-1">库存列表 <a class="header-anchor" href="#库存列表" aria-label="Permalink to &quot;库存列表&quot;">​</a></h1><blockquote><p>&quot;入库列表“位于仓储管理板块，是从仓储管理的 ”入库列表“ 中入库以后流转到库存列表中的信息</p></blockquote><h4 id="_1-系列分类" tabindex="-1">1.系列分类 <a class="header-anchor" href="#_1-系列分类" aria-label="Permalink to &quot;1.系列分类&quot;">​</a></h4><ul><li><p>在所有系列中，双击可编辑系列的名称</p></li><li><p>在其他系列中，可新增系列，双击编辑系列名称，新增的系列支持添加，删除</p></li></ul><h4 id="_2-新增" tabindex="-1">2. 新增 <a class="header-anchor" href="#_2-新增" aria-label="Permalink to &quot;2. 新增&quot;">​</a></h4><ul><li>选中系列，再点击新增可新增物料</li></ul><h4 id="_3-批量编辑" tabindex="-1">3. 批量编辑 <a class="header-anchor" href="#_3-批量编辑" aria-label="Permalink to &quot;3. 批量编辑&quot;">​</a></h4><ul><li>勾选需要编辑的产品可批量编辑它的盘点周期，安全库存，状态，库存上限，仓位，备注</li></ul><p><img src="'+r+'" alt="如图所示"></p><h4 id="_4-编辑" tabindex="-1">4.编辑 <a class="header-anchor" href="#_4-编辑" aria-label="Permalink to &quot;4.编辑&quot;">​</a></h4><ul><li><p>点击编辑按钮可选择盘点周期，可输入安全库存，选择启用/停用状态，输入库存上限</p><p>-列：如果输入库存上限是100，当采购时超出了库存上限100，将提示:采购后将超过库存上限，是否继续的提示语</p></li><li><p>可添加仓位，变更仓位，添加的仓位支持删除</p></li></ul><h4 id="_5-盘点" tabindex="-1">5.盘点 <a class="header-anchor" href="#_5-盘点" aria-label="Permalink to &quot;5.盘点&quot;">​</a></h4><ul><li>选择盘点类型，在对应的仓位中，输入 完好数量，准备信息，系统会根据账面数量自动算出损坏或过期的数量</li></ul><p><img src="'+o+'" alt="如图所示"></p><h4 id="_6-导出" tabindex="-1">6.导出 <a class="header-anchor" href="#_6-导出" aria-label="Permalink to &quot;6.导出&quot;">​</a></h4><ul><li>点击导出按键，出现导出弹窗，可在输入框中输入需导出数据数量，点击导出后，页面出现“数据导出中”提示弹窗，当导出任务结束时，可在本地查看导出文件</li></ul><h4 id="_7-导入" tabindex="-1">7.导入 <a class="header-anchor" href="#_7-导入" aria-label="Permalink to &quot;7.导入&quot;">​</a></h4><ul><li><p>点击导入，先下载模板（注意下载的模板只适用于批量导入库存列表里面上传的模板)</p></li><li><p>点开下载的模板进行编辑（编辑时请阅读表格上面的提示文案，以防导入时出现错误，从而无法导入）</p></li><li><p>点击或者拖拽所保存的模板（只有在库存列表的批量导入中下载的模板才能上传，其他无效）进行上传</p></li><li><p>上传成功会弹出显示上传的数据，可选择性导入或者一键导入（如果无法导入，请滑动到页面最后，查看提示信息，可能存在编辑时出现的错误，需从新更改再次上传）、</p></li></ul><h4 id="_8-库存量" tabindex="-1">8.库存量 <a class="header-anchor" href="#_8-库存量" aria-label="Permalink to &quot;8.库存量&quot;">​</a></h4><ul><li>点击可查看盘点的详细记录</li></ul><h4 id="_9-仓位" tabindex="-1">9.仓位 <a class="header-anchor" href="#_9-仓位" aria-label="Permalink to &quot;9.仓位&quot;">​</a></h4><ul><li>点击可查看这个产品所对应的所有仓位信息，支持批次查询</li></ul><p><img src="'+h+'" alt="如图所示"></p><h1 id="盘点记录" tabindex="-1">盘点记录 <a class="header-anchor" href="#盘点记录" aria-label="Permalink to &quot;盘点记录&quot;">​</a></h1><h4 id="_1导出" tabindex="-1">1导出 <a class="header-anchor" href="#_1导出" aria-label="Permalink to &quot;1导出&quot;">​</a></h4><ul><li><p>点击批量导出按钮可将库存列表里面的产品/部件等导出来</p><p>-可一键选择导出或手动输入n条进行导出</p></li></ul><h4 id="_2-实盘总量" tabindex="-1">2.实盘总量 <a class="header-anchor" href="#_2-实盘总量" aria-label="Permalink to &quot;2.实盘总量&quot;">​</a></h4><p>可查看实盘总量的详情包括仓位，批次号，账面数量，完好数量，损坏/过期数量，备注信息</p><h4 id="_3-盘点人" tabindex="-1">3.盘点人 <a class="header-anchor" href="#_3-盘点人" aria-label="Permalink to &quot;3.盘点人&quot;">​</a></h4><ul><li>鼠标悬浮在盘点人员上面可查看人员的基本信息（姓名，部门，电话）</li></ul><h4 id="_4-重置" tabindex="-1">4.重置 <a class="header-anchor" href="#_4-重置" aria-label="Permalink to &quot;4.重置&quot;">​</a></h4><ul><li>点击重置按键后，重置查询条件，恢复到默认</li></ul><p><img src="'+s+'" alt="如图所示"></p>',33)])])}const f=l(n,[["render",c]]);export{m as __pageData,f as default};
